     2	import java.util.Arrays;
     3	import java.util.HashSet;
     4	import java.util.Iterator;
     5	import java.util.List;
     6	import java.util.Set;
     7	
     8	/**
     9	 * A simple model of a Hunter.
    10	 * Hunters age, move, hunt lions and cheetahs at night, and die.
    11	 * A new hunter spawns nearby every SPAWN_INTERVAL steps.
    12	 *
    13	 * @version 2022.03.01
    14	 */
    15	public class Hunter extends Actor
    16	
    17	{
    18	    // Characteristics shared by all Hunters.
    19	    private static final int MAX_AGE = 1000;
    20	    private static final int SHOTS = 2;
    21	    // A new hunter spawns every this many simulation steps.
    22	    private static final int SPAWN_INTERVAL = 898;
    23	    private static final Set<Class<? extends Actor>> HUNTABLE_SPECIES = new HashSet<>(Arrays.asList(Lion.class, Cheetah.class));
    24	    /**
    25	     * Create a Hunter. A hunter is created as an adult (age 50).
    26	     * 
    27	     * @param field The field currently occupied.
    28	     * @param location The location within the field.
    29	     */
    30	    public Hunter(Field field, Location location)
    31	    {
    32	        super(field, location);
    33	        setAge(50);
    34	    }
    35	
    36	    /**
    37	     * This is what the Hunter does most of the time: it hunts
    38	     * lions during the night. In the process, it might die of old age.
    39	     * 
    40	     * @param newHunters A list to return new Hunters.
    41	     * @param simulator The simulator.
    42	     */
    43	    public void act(List<Actor> newHunters,Simulator simulator){
    44	        incrementAge(simulator.getSteps());
    45	        if(!simulator.isDay()){
    46	            if(isActive() ) {
    47	                hunt(getHuntProbability(simulator.getWeather()));
    48	                Field field = getField();
    49	                Location newLocation = field.freeAdjacentLocation(getLocation());
    50	                if(newLocation != null) {
    51	                    setLocation(newLocation);
    52	                } 
    53	                if(simulator.getSteps() % SPAWN_INTERVAL == 0) {
    54	                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
    55	                    if(!free.isEmpty()) {
    56	                        Location loc = free.remove(0);
    57	                        Hunter hunter = new Hunter(field, loc);
    58	                        newHunters.add(hunter);
    59	                    }
    60	                }
    61	            }
    62	        }
    63	    }
    64	
    65	    private double getHuntProbability(Weather weather) {
    66	        switch(weather) {
    67	            case RAINY: return 0.7;
    68	            case FOGGY: return 0.4;
    69	            default:    return getRandom().nextDouble();
    70	        }
    71	    }
    72	
    73	    /**
    74	     * This determine how the hunter hunts nearby lions
    75	     * The hunter has 2 shots.
    76	     * @param probability The probability the hunting is successful.
    77	     */
    78	    private void hunt(double probability){
    79	        if(getRandom().nextDouble() < probability){
    80	            Field field = getField();
    81	            List<Location> adjacent = field.adjacentLocations(getLocation());
    82	            Iterator<Location> it = adjacent.iterator();
    83	            for(int i = 0; i < SHOTS && it.hasNext(); i++){
    84	                Location where = it.next();
    85	                Object animal = field.getObjectAt(where);
    86	                if(animal != null && HUNTABLE_SPECIES.contains(animal.getClass())){
    87	                    Animal currentAnimal = (Animal) animal;
    88	                    if(currentAnimal.isActive()) {
    89	                        currentAnimal.setDead();
    90	                        break;
    91	                    }
    92	                }
    93	            }
    94	        }
    95	    }
    96	
    97	    /**
    98	     * Gets the max age of a hunter.
    99	     * @return int. Max age of the hunter.
   100	     */
   101	    protected int getMaxAge(){
   102	        return MAX_AGE;
   103	    }
   104	}
