     4	/**
     5	 * Provide control over the randomization of the simulation. By using the shared, fixed-seed 
     6	 * randomizer, repeated runs will perform exactly the same (which helps with testing). Set 
     7	 * 'useShared' to false to get different random behaviour every time.
     8	 *
     9	 * @version 2016.02.29
    10	 */
    11	public class Randomizer
    12	{
    13	    // The default seed for control of randomization.
    14	    private static final int SEED = 1111;
    15	    // A shared Random object, if required.
    16	    private static final Random rand = new Random(SEED);
    17	    // Determine whether a shared random generator is to be provided.
    18	    private static final boolean useShared = true;
    19	
    20	    private Randomizer() {}
    21	
    22	    /**
    23	     * Provide a random generator.
    24	     * @return A random object.
    25	     */
    26	    public static Random getRandom()
    27	    {
    28	        if(useShared) {
    29	            return rand;
    30	        }
    31	        else {
    32	            return new Random();
    33	        }
    34	    }
    35	    
    36	    /**
    37	     * Reset the randomization.
    38	     * This will have no effect if randomization is not through
    39	     * a shared Random generator.
    40	     */
    41	    public static void reset()
    42	    {
    43	        if(useShared) {
    44	            rand.setSeed(SEED);
    45	        }
    46	    }
    47	}
