     4	 * Sets the time based on the number of steps in the simulator.
     5	 *
     6	 * @version 2022.03.01
     7	 */
     8	public class Timer
     9	{
    10	    private String currentTime;
    11	    private String minutes;
    12	    private static final Random random = Randomizer.getRandom();
    13	    
    14	    /**
    15	     * Constructor for objects of class Timer
    16	     */
    17	    public Timer()
    18	    {
    19	        
    20	    }
    21	    
    22	    /**
    23	     * Generates a random time between 6 and 11am.
    24	     */
    25	    public String getMorningTime(){
    26	        currentTime = Integer.toString(random.nextInt(6) + 6);
    27	        return currentTime;
    28	    }
    29	
    30	    /**
    31	     * Generates a random time between 12 and 5pm.
    32	     */
    33	    public String getAfternoonTime(){
    34	        currentTime = Integer.toString(random.nextInt(6) + 12);
    35	        return currentTime;
    36	    }
    37	
    38	    /**
    39	     * Generates a random time between 6 and 11pm.
    40	     */
    41	    public String getEveningTime(){
    42	        currentTime = Integer.toString(random.nextInt(6) + 18);
    43	        return currentTime;
    44	    }
    45	
    46	    /**
    47	     * Generates a random time between 12 and 5am.
    48	     */
    49	    public String getNightTime(){
    50	        currentTime =Integer.toString(random.nextInt(6));
    51	        return currentTime;
    52	    }
    53	
    54	    /**
    55	     * Adds ":" to the current time string + minutes
    56	     * @return the current time string with ':' + minutes.
    57	     */
    58	    @Override
    59	    public String toString(){
    60	        return currentTime +":" + minutes;
    61	    }
    62	    
    63	    /**
    64	     * Randomly generates minutes.
    65	     * @return minutes as a string.
    66	     */
    67	    public String getMinutes(){
    68	        int min = random.nextInt(60);
    69	        minutes = Integer.toString(min);
    70	        if(min < 10){
    71	            minutes = "0" + minutes;
    72	        }
    73	        return minutes;
    74	    }
    75	
    76	    /**
    77	     * Uses the step number to decide what time of day it is to randomly generate an apporopriate time.
    78	     * @param steps. The step number currently in the simulation.
    79	     * @return Current time in the simualtion.
    80	     */
    81	    public String getTime(int steps){
    82	        switch(steps % 4) {
    83	            case 0:  getMorningTime();   break;
    84	            case 1:  getAfternoonTime(); break;
    85	            case 2:  getEveningTime();   break;
    86	            default: getNightTime();     break;
    87	        }
    88	        getMinutes();
    89	        return toString();
    90	    }
    91	}
